public static void main(String[] args) {
    var sc = new Scanner(System.in);

    int n = Integer.parseInt(sc.next());
    int m = Integer.parseInt(sc.next());
    var x = new int[m];
    for(int i = 0; i < m; i++){
        x[i] = Integer.parseInt(sc.next());
    }

    // Sort the array x to calculate the distances between consecutive islands
    Arrays.sort(x);

    // Calculate the initial tour length
    long totalDistance = 0;
    for(int i = 0; i < m - 1; i++){
        totalDistance += x[i+1] - x[i];
    }

    // If there are more islands than bridges, no need to close any bridge
    if (n >= m) {
        System.out.println(0);
        return;
    }

    // Calculate the distances between consecutive islands and sort them
    long[] distances = new long[m - 1];
    for(int i = 0; i < m - 1; i++){
        distances[i] = x[i+1] - x[i];
    }
    Arrays.sort(distances);

    // Close the largest (m-n) distances to minimize the tour length
    for(int i = 0; i < m - n; i++){
        totalDistance -= distances[m - 2 - i];
    }

    System.out.println(totalDistance);
}
